"C:\\Program Files\\PowerShell\\7\\pwsh.exe" -Command '$ErrorActionPreference = '"'Stop'
"'$container = '"'rawsqlcandidate786cf75912cc4b51bd6f64368f4cf5a5'
"'$ready = $false
for ($attempt = 1; $attempt -le 60; $attempt++) {
  docker exec $container pg_isready -U postgres -d postgres *> $null
  if ($LASTEXITCODE -eq 0) { $ready = $true; break }
  Start-Sleep -Seconds 1
}
if (-not $ready) { throw '"'PostgreSQL did not accept connections within 60 seconds.' }
docker exec "'$container psql -v ON_ERROR_STOP=1 -U postgres -d postgres -c "CREATE TABLE candidate_probe(id int primary key, note text);"
if ($LASTEXITCODE -ne 0) { throw '"'CREATE TABLE failed.' }
docker exec "'$container psql -v ON_ERROR_STOP=1 -U postgres -d postgres -c "INSERT INTO candidate_probe(id, note) VALUES (1, '"'candidate-created');\"
if ("'$LASTEXITCODE -ne 0) { throw '"'INSERT failed.' }
"'$result = docker exec $container psql -v ON_ERROR_STOP=1 -At -U postgres -d postgres -c "SELECT id || '"'|' || note FROM candidate_probe WHERE id = 1;\"
if ("'$LASTEXITCODE -ne 0 -or $result.Trim() -ne '"'1|candidate-created') { throw \"Unexpected verification result: "'$result" }
$result'

